import {
  MapContainer,
  TileLayer,
  Polyline,
  Marker,
  Tooltip,
} from "react-leaflet";
import { useEffect, useState } from "react";
import axios from "axios";
import L from "leaflet";

// Fix marker
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl:
    "https://unpkg.com/leaflet@1.7.1/dist/images/marker-icon-2x.png",
  iconUrl:
    "https://unpkg.com/leaflet@1.7.1/dist/images/marker-icon.png",
  shadowUrl:
    "https://unpkg.com/leaflet@1.7.1/dist/images/marker-shadow.png",
});

function App() {
  const [data, setData] = useState([]);
  const [path, setPath] = useState([]);

  const [startTime, setStartTime] = useState("");
  const [endTime, setEndTime] = useState("");

  const [currentIndex, setCurrentIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);

  // 🚀 Fetch data
  const fetchData = async (start, end) => {
    try {
      let url = "http://localhost:3000/path";

      if (start && end) {
        url += `?start=${start}&end=${end}`;
      }

      console.log("📡 API:", url);

      const res = await axios.get(url);

      const formatted = res.data
        .filter(
          (d) =>
            d &&
            d.location &&
            d.location.coordinates &&
            d.location.coordinates.length === 2
        )
        .map((d, i) => ({
          lat: d.location.coordinates[1],
          lon: d.location.coordinates[0],
          alt: d.alt || 0,
          timestamp: new Date(d.timestamp),
          index: i,
        }));

      console.log("📊 FRONT COUNT:", formatted.length);

      setData(formatted);

      if (formatted.length > 0) {
        setPath([formatted[0]]);
        setCurrentIndex(0);
      }

    } catch (err) {
      console.error(err);
    }
  };

  // 🔥 Initial load
  useEffect(() => {
    fetchData();
  }, []);

  // 🎯 Apply filter
  const applyFilter = () => {
    if (!startTime || !endTime) {
      alert("Select both times");
      return;
    }

    fetchData(
      new Date(startTime).toISOString(),
      new Date(endTime).toISOString()
    );
  };

  // 🎬 Playback
  useEffect(() => {
    if (!isPlaying || data.length === 0) return;

    const interval = setInterval(() => {
      setCurrentIndex((prev) => {
        if (prev >= data.length - 1) {
          clearInterval(interval);
          setIsPlaying(false);
          return prev;
        }

        setPath(data.slice(0, prev + 1));
        return prev + 1;
      });
    }, 200);

    return () => clearInterval(interval);
  }, [isPlaying, data]);

  // 🎯 Slider
  const handleSlider = (e) => {
    const index = Number(e.target.value);
    setCurrentIndex(index);
    setPath(data.slice(0, index + 1));
  };

  return (
    <div style={{ padding: "10px" }}>
      <h2>🚁 Drone Timeline (Fully Fixed)</h2>

      {/* ⏱️ Time Inputs */}
      <input
        type="datetime-local"
        onChange={(e) => setStartTime(e.target.value)}
      />

      <input
        type="datetime-local"
        onChange={(e) => setEndTime(e.target.value)}
        style={{ marginLeft: "10px" }}
      />

      <button onClick={applyFilter} style={{ marginLeft: "10px" }}>
        Apply
      </button>

      <br /><br />

      {/* 🎮 Controls */}
      <button onClick={() => setIsPlaying(true)}>▶ Play</button>
      <button onClick={() => setIsPlaying(false)}>⏸ Pause</button>

      <input
        type="range"
        min="0"
        max={data.length > 0 ? data.length - 1 : 0}
        value={currentIndex}
        onChange={handleSlider}
        style={{ width: "50%", marginLeft: "10px" }}
      />

      <span style={{ marginLeft: "10px" }}>
        {data[currentIndex]?.timestamp?.toLocaleString()}
      </span>

      {/* 🗺️ Map */}
      <MapContainer
        center={[12.9716, 77.5946]}
        zoom={18}
        style={{ height: "70vh", width: "100%" }}
      >
        <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />

        <Polyline
          positions={path.map((p) => [p.lat, p.lon])}
          color="cyan"
        />

        {path.length > 0 && (
          <Marker
            position={[
              path[path.length - 1].lat,
              path[path.length - 1].lon,
            ]}
          >
            <Tooltip>
              Alt: {path[path.length - 1].alt.toFixed(2)} m
            </Tooltip>
          </Marker>
        )}
      </MapContainer>
    </div>
  );
}

export default App;
